-- Sanitized production-derived sample, prepared 2026-10-26.
-- Customer, order, stock, and product IDs are remapped. No source ID mapping is retained.
-- All credentials, personal data, order dates, prices, totals, and free-form customer data are replaced.
BEGIN;
SELECT setval(pg_get_serial_sequence('public."countries"', 'id'), (SELECT max(id) FROM public."countries"));
SELECT setval(pg_get_serial_sequence('public."regions"', 'id'), (SELECT max(id) FROM public."regions"));
SELECT setval(pg_get_serial_sequence('public."categories"', 'id'), (SELECT max(id) FROM public."categories"));
SELECT setval(pg_get_serial_sequence('public."agents"', 'id'), (SELECT max(id) FROM public."agents"));
SELECT setval(pg_get_serial_sequence('public."sales_channels"', 'id'), (SELECT max(id) FROM public."sales_channels"));
SELECT setval(pg_get_serial_sequence('public."shop_groups"', 'id'), (SELECT max(id) FROM public."shop_groups"));
SELECT setval(pg_get_serial_sequence('public."users"', 'id'), (SELECT max(id) FROM public."users"));
SELECT setval(pg_get_serial_sequence('public."customers"', 'id'), (SELECT max(id) FROM public."customers"));
SELECT setval(pg_get_serial_sequence('public."products"', 'id'), (SELECT max(id) FROM public."products"));
SELECT setval(pg_get_serial_sequence('public."product_stocks"', 'id'), (SELECT max(id) FROM public."product_stocks"));
SELECT setval(pg_get_serial_sequence('public."orders"', 'id'), (SELECT max(id) FROM public."orders"));
SELECT setval(pg_get_serial_sequence('public."order_details"', 'id'), (SELECT max(id) FROM public."order_details"));
COMMIT;
